<?php

namespace App\Models;

use App\Services\CostCalculator;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\HasOne;

class Recipe extends Model
{
    protected $guarded = [];

    protected function casts(): array
    {
        return [
            'yield_quantity' => 'float',
        ];
    }

    public function stages()
    {
        return $this->hasMany(Stage::class)->orderBy('order');
    }

    public function recipeItems()
    {
        return $this->hasMany(RecipeItem::class);
    }

    /**
     * Item generated by this recipe when it is used as a preparation.
     */
    public function item(): HasOne
    {
        return $this->hasOne(Item::class);
    }

    /**
     * Calculate direct costs (ingredients, labor, packaging, direct_cost)
     */
    public function calculateDirectCost(): float
    {
        return app(CostCalculator::class)->recipeDirectCost($this);
    }

    /**
     * Calculate item cost in context of this recipe (handles percentage overheads)
     */
    public function calculateItemCost(RecipeItem $recipeItem, ?float $directCost = null): float
    {
        return app(CostCalculator::class)->recipeItemCost($this, $recipeItem, $directCost);
    }

    /**
     * Calculate total overhead cost (both fixed and percentage based on direct cost)
     */
    public function calculateOverheadCost(?float $directCost = null): float
    {
        return app(CostCalculator::class)->recipeOverheadCost($this, $directCost);
    }

    /**
     * Calculate total recipe cost (direct + overhead)
     */
    public function calculateTotalCost(): float
    {
        return app(CostCalculator::class)->recipeTotal($this);
    }

    /**
     * Cost of one yield unit of this recipe.
     */
    public function calculateUnitCost(): float
    {
        return app(CostCalculator::class)->recipeUnitCost($this);
    }

    /**
     * Determine if this recipe is published as a preparation item.
     */
    public function isPreparation(): bool
    {
        return $this->item()->exists();
    }

    /**
     * Determine if the preparation item is consumed by other recipes.
     */
    public function isUsedAsItem(): bool
    {
        return $this->item()->whereHas('recipeItems')->exists();
    }

    /**
     * Determine if this recipe depends (transitively) on the target recipe.
     */
    public function dependsOn(Recipe $target, array $visited = []): bool
    {
        if (in_array($this->id, $visited, true)) {
            return false;
        }

        $visited[] = $this->id;

        $this->loadMissing('stages.recipeItems.item.recipe');

        foreach ($this->stages as $stage) {
            foreach ($stage->recipeItems as $recipeItem) {
                $item = $recipeItem->item;

                if (! $item?->isPreparation() || ! $item->recipe) {
                    continue;
                }

                if ($item->recipe->id === $target->id || $item->recipe->dependsOn($target, $visited)) {
                    return true;
                }
            }
        }

        return false;
    }

    protected static function booted(): void
    {
        static::deleting(function (Recipe $recipe) {
            $item = $recipe->item()->first();

            if ($item && $item->isUsedInRecipes()) {
                return false;
            }

            if ($item && ! $item->delete()) {
                return false;
            }

            return true;
        });
    }
}
